content.process:
pt = get_plugin('PubTatorRelationExtractor')
text = (state.get('text') or '').strip()
pmid = str(state.get('pmid') or '').strip()
entities = state.get('entities') or {}
if not pt:
    state['error'] = 'PubTatorRelationExtractor plugin unavailable'
    __result__ = []
elif not text and not pmid:
    state['error'] = "Missing 'text' or 'pmid'"
    __result__ = []
else:
    try:
        payload = pt.extract_relations(text=text, pmid=pmid, entities=entities)
        __result__ = payload.get('relations') or []
        if payload.get('raw_relations') is not None:
            state['pubtator_raw_relations'] = payload.get('raw_relations')
        if payload.get('source'):
            state['pubtator_source'] = payload.get('source')
        if payload.get('error'):
            state['error'] = payload.get('error')
    except Exception as ex:
        state['error'] = f'PubTator relation extraction failed: {ex}'
        __result__ = []
